gsap:
// glow: drop-shadow na cor de acento
tl.fromTo(el, { filter: "drop-shadow(0 0 0px rgba(208,89,44,0))" }, { filter: "drop-shadow(0 0 40px rgba(208,89,44,0.9))", duration: 0.25, ease: "power2.out" }, t);
tl.to(el, { filter: "drop-shadow(0 0 0px rgba(208,89,44,0))", duration: 0.5, ease: "power2.in" }, t + 0.35);

// wiggle: repeat finito
tl.fromTo(el, { rotation: -2 }, { rotation: 2, duration: 0.12, ease: "sine.inOut", yoyo: true, repeat: 7 }, t);
tl.to(el, { rotation: 0, duration: 0.1 }, t + 0.96);

// color pop: "tint" é uma cópia do elemento já pintada na cor de acento, empilhada por cima (a = tint)
tl.fromTo(a, { opacity: 0 }, { opacity: 1, duration: 0.15, ease: "power2.out" }, t);
tl.fromTo(el, { scale: 1 }, { scale: 1.06, duration: 0.15, ease: "power2.out", yoyo: true, repeat: 1 }, t);

// magnetic pull: deslocamentos pré-calculados (dx,dy até o alvo × 0.15)
const pulls = [[40, 30], [-35, 25], [30, -40], [-25, -30]];
items.forEach((it, i) => {
  const [dx, dy] = pulls[i % pulls.length];
  tl.fromTo(it, { x: 0, y: 0 }, { x: dx, y: dy, duration: 0.5, ease: "power3.out" }, t);
  tl.to(it, { x: 0, y: 0, duration: 0.8, ease: "elastic.out(1, 0.5)" }, t + 1.2);
});

// nudge: para a direita (troque x por y para cima/baixo)
tl.fromTo(el, { x: 0 }, { x: 16, duration: 0.12, ease: "power2.out" }, t);
tl.to(el, { x: 0, duration: 0.3, ease: "back.out(2)" }, t + 0.12);

// scale emphasis: cresce, segura, volta
const hold = 1.5;
tl.fromTo(el, { scale: 1 }, { scale: 1.2, duration: 0.35, ease: "power3.out" }, t);
tl.to(el, { scale: 1, duration: 0.35, ease: "power2.inOut" }, t + 0.35 + hold);

// spotlight dim: items = os outros; el = o destacado
tl.fromTo(items, { opacity: 1, filter: "brightness(1)" }, { opacity: 0.25, filter: "brightness(0.6)", duration: 0.4, ease: "power2.out" }, t);
tl.fromTo(el, { scale: 1 }, { scale: 1.05, duration: 0.4, ease: "power2.out" }, t);
